local f = CreateFrame("Frame")
f:RegisterEvent("PLAYER_LOGIN")
f:SetScript("OnEvent", function()
	local A = _G.PintsQuestAreas
	if not (A and NS.MapToWorld and C_Map and C_Map.GetMapChildrenInfo) then return end
	local uiMap = {}
	for _, root in ipairs({ 947, 946 }) do
		local ok, kids = pcall(C_Map.GetMapChildrenInfo, root, nil, true)
		if ok and kids then for _, m in ipairs(kids) do if m.name and not uiMap[m.name] then uiMap[m.name] = m.mapID end end end
	end
	for qid, objs in pairs(AREAS) do
		if not A[qid] then
			local out = {}
			for _, o in ipairs(objs) do
				local m = uiMap[o[2]]
				if m then
					local e = { o[1] }
					for k = 3, #o, 2 do
						local cont, wx, wy = NS.MapToWorld(m, o[k], o[k + 1])
						if cont and wx then e[#e + 1] = cont; e[#e + 1] = wx; e[#e + 1] = wy end
					end
					if #e > 1 then out[#out + 1] = e end
				end
			end
			if #out > 0 then A[qid] = out end
		end
	end
end)
